-- Suggested PostgreSQL/PostGIS production schema baseline (not used by the local JSON demo).
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TYPE user_role AS ENUM ('rider','driver','admin');
CREATE TYPE review_status AS ENUM ('pending','approved','rejected');
CREATE TYPE ride_status AS ENUM ('OPEN','FULL','CLOSED');
CREATE TYPE booking_status AS ENUM ('REQUESTED','MATCHED','ACCEPTED','DRIVER_EN_ROUTE','STARTED','COMPLETED','CANCELLED_BY_RIDER','CANCELLED_BY_DRIVER','NO_SHOW','REJECTED');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL, name text NOT NULL, email text UNIQUE, phone text UNIQUE, password_hash text NOT NULL, photo_url text, phone_verified boolean NOT NULL DEFAULT false, verified_status review_status NOT NULL DEFAULT 'pending', emergency_contacts jsonb NOT NULL DEFAULT '[]', rating_avg numeric(2,1) NOT NULL DEFAULT 0, is_blocked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES users(id), number text NOT NULL UNIQUE, model text NOT NULL, vehicle_type text NOT NULL DEFAULT 'Car', seats integer NOT NULL CHECK (seats BETWEEN 1 AND 8));
CREATE TABLE driver_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), licence_no text, vehicle_id uuid REFERENCES vehicles(id), document_urls jsonb NOT NULL DEFAULT '[]', background_check_status review_status NOT NULL DEFAULT 'pending', is_online boolean NOT NULL DEFAULT false);
CREATE TABLE nodal_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, location geography(Point,4326) NOT NULL, city text NOT NULL DEFAULT 'Bharuch', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX nodal_points_location_gix ON nodal_points USING GIST(location);
CREATE TABLE plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role user_role NOT NULL, name text NOT NULL, price_inr numeric(10,2) NOT NULL CHECK(price_inr>=0), duration_days integer NOT NULL CHECK(duration_days>0), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), plan_id uuid NOT NULL REFERENCES plans(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status text NOT NULL, payment_method text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX subscriptions_user_active_idx ON subscriptions(user_id,status,end_at);
CREATE TABLE ride_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL REFERENCES users(id), origin_node_id uuid NOT NULL REFERENCES nodal_points(id), dest_node_id uuid NOT NULL REFERENCES nodal_points(id), departure_time timestamptz NOT NULL, seats_total integer NOT NULL CHECK(seats_total BETWEEN 1 AND 8), seats_available integer NOT NULL CHECK(seats_available BETWEEN 0 AND seats_total), fare_per_seat numeric(10,2) NOT NULL CHECK(fare_per_seat>=0), ride_type text NOT NULL CHECK(ride_type IN ('POOL','SOLO')), status ride_status NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL REFERENCES users(id), driver_id uuid NOT NULL REFERENCES users(id), ride_post_id uuid NOT NULL REFERENCES ride_posts(id), pickup_node_id uuid NOT NULL REFERENCES nodal_points(id), drop_node_id uuid NOT NULL REFERENCES nodal_points(id), ride_type text NOT NULL CHECK(ride_type IN ('POOL','SOLO')), agreed_fare numeric(10,2) NOT NULL, status booking_status NOT NULL DEFAULT 'REQUESTED', payment_status text NOT NULL DEFAULT 'PENDING', cancel_reason text, share_token_hash text, started_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid REFERENCES bookings(id), subscription_id uuid REFERENCES subscriptions(id), user_id uuid REFERENCES users(id), method text NOT NULL CHECK(method IN ('CASH','CARD','UPI')), amount numeric(10,2) NOT NULL, status text NOT NULL, provider_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ratings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), from_user uuid NOT NULL REFERENCES users(id), to_user uuid NOT NULL REFERENCES users(id), stars integer NOT NULL CHECK(stars BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(booking_id,from_user));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), sender_id uuid NOT NULL REFERENCES users(id), text text NOT NULL CHECK(length(text)<=1000), sent_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE live_locations (booking_id uuid NOT NULL REFERENCES bookings(id), user_id uuid NOT NULL REFERENCES users(id), location geography(Point,4326) NOT NULL, accuracy_m numeric, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(booking_id,user_id));
CREATE INDEX live_locations_gix ON live_locations USING GIST(location);
CREATE TABLE sos_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), booking_id uuid REFERENCES bookings(id), location geography(Point,4326), note text, status text NOT NULL DEFAULT 'OPEN', resolved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), category text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'OPEN', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), type text NOT NULL, message text NOT NULL, booking_id uuid REFERENCES bookings(id), is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
